use "./sim.ts" { Ball, step, draw }

component BallSimulation {
  ref canvas
  ref simulationRef

  state paused = false
  state ballCount = 5
  state frameCount = 0

  fn initSimulation() {
    frameCount = 0
    const balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(new Ball(
        Math.random() * 380 + 10,
        Math.random() * 280 + 10,
        (Math.random() - 0.5) * 4,
        (Math.random() - 0.5) * 4,
        10
      ))
    }
    simulationRef = { balls, animationId: null }
    ballCount = 5
    startAnimation()
  }

  fn startAnimation() {
    if simulationRef.animationId != null { return }

    const animate = () => {
      if !paused {
        step(simulationRef.balls, 0.2, 400, 300)
        const ctx = canvas.getContext("2d")
        ctx.fillStyle = "#ffffff"
        ctx.fillRect(0, 0, 400, 300)
        draw(ctx, simulationRef.balls)
        frameCount++
      }
      simulationRef.animationId = requestAnimationFrame(animate)
    }
    simulationRef.animationId = requestAnimationFrame(animate)
  }

  fn stopAnimation() {
    if simulationRef.animationId != null {
      cancelAnimationFrame(simulationRef.animationId)
      simulationRef.animationId = null
    }
  }

  fn togglePause() {
    paused = !paused
    if !paused && simulationRef.animationId == null {
      startAnimation()
    }
  }

  fn addBall() {
    simulationRef.balls.push(new Ball(
      Math.random() * 380 + 10,
      Math.random() * 280 + 10,
      (Math.random() - 0.5) * 4,
      (Math.random() - 0.5) * 4,
      10
    ))
    ballCount++
  }

  mount {
    initSimulation()
    cleanup {
      stopAnimation()
    }
  }

  column gap=4 pad=4 {
    row gap=2 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> initSimulation()
    }
    row gap=4 {
      text `Pelotas: ${ballCount}`
      text `Cuadros: ${frameCount}`
    }
    canvas id=sim ref=canvas width=400 height=300 style="border: 1px solid #ccc; background: white; display: block;"
  }
}

