export class Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;

  constructor(x: number, y: number, vx: number, vy: number, r: number) {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.r = r;
  }
}

export function step(balls: Ball[], gravity: number, w: number, h: number) {
  // Apply gravity
  for (const b of balls) {
    b.vy += gravity;
  }

  // Update positions
  for (const b of balls) {
    b.x += b.vx;
    b.y += b.vy;
  }

  // Bounce off walls
  for (const b of balls) {
    if (b.x - b.r < 0) {
      b.x = b.r;
      b.vx = -b.vx;
    }
    if (b.x + b.r > w) {
      b.x = w - b.r;
      b.vx = -b.vx;
    }
    if (b.y - b.r < 0) {
      b.y = b.r;
      b.vy = -b.vy;
    }
    if (b.y + b.r > h) {
      b.y = h - b.r;
      b.vy = -b.vy;
    }
  }

  // Elastic collision between balls
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i];
      const b2 = balls[j];
      const dx = b2.x - b1.x;
      const dy = b2.y - b1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < b1.r + b2.r) {
        // Exchange velocities (simplified elastic collision for equal mass)
        const temp_vx = b1.vx;
        const temp_vy = b1.vy;
        b1.vx = b2.vx;
        b1.vy = b2.vy;
        b2.vx = temp_vx;
        b2.vy = temp_vy;

        // Separate balls to prevent overlap
        const overlap = (b1.r + b2.r - dist) / 2;
        const nx = dx / dist;
        const ny = dy / dist;
        b1.x -= nx * overlap;
        b1.y -= ny * overlap;
        b2.x += nx * overlap;
        b2.y += ny * overlap;
      }
    }
  }
}

export function draw(ctx: CanvasRenderingContext2D, balls: Ball[]) {
  ctx.fillStyle = "#e11d48";
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

